105	#define WRITE_CHECK(fp, ptr, count)                                            \
106	  if (fp.write((ptr), (count)) != (count)) {                                   \
107	    throw DL_ABORT_EX(fmt(EX_SEGMENT_FILE_WRITE, filename_.c_str()));          \
108	  }
