110	// Since version 0001, Integers are saved in binary form, network byte order.
111	void DefaultBtProgressInfoFile::save(IOFile& fp)
112	{
113	#ifdef ENABLE_BITTORRENT
114	  bool torrentDownload = isTorrentDownload();
115	#else  // !ENABLE_BITTORRENT
116	  bool torrentDownload = false;
117	#endif // !ENABLE_BITTORRENT
118	  // file version: 16 bits
119	  // values: '1'
120	  char version[] = {0x00u, 0x01u};
121	  WRITE_CHECK(fp, version, sizeof(version));
122	  // extension: 32 bits
123	  // If this is BitTorrent download, then 0x00000001
124	  // Otherwise, 0x00000000
125	  char extension[4];
126	  memset(extension, 0, sizeof(extension));
127	  if (torrentDownload) {
128	    extension[3] = 1;
129	  }
130	  WRITE_CHECK(fp, extension, sizeof(extension));
131	  if (torrentDownload) {
132	#ifdef ENABLE_BITTORRENT
133	    // infoHashLength:
134	    // length: 32 bits
135	    const unsigned char* infoHash = bittorrent::getInfoHash(dctx_);
136	    uint32_t infoHashLengthNL = htonl(INFO_HASH_LENGTH);
137	    WRITE_CHECK(fp, &infoHashLengthNL, sizeof(infoHashLengthNL));
138	    // infoHash:
139	    WRITE_CHECK(fp, infoHash, INFO_HASH_LENGTH);
140	#endif // ENABLE_BITTORRENT
141	  }
142	  else {
143	    // infoHashLength:
144	    // length: 32 bits
145	    uint32_t infoHashLength = 0;
146	    WRITE_CHECK(fp, &infoHashLength, sizeof(infoHashLength));
147	  }
148	  // pieceLength: 32 bits
149	  uint32_t pieceLengthNL = htonl(dctx_->getPieceLength());
150	  WRITE_CHECK(fp, &pieceLengthNL, sizeof(pieceLengthNL));
151	  // totalLength: 64 bits
152	  uint64_t totalLengthNL = hton64(dctx_->getTotalLength());
153	  WRITE_CHECK(fp, &totalLengthNL, sizeof(totalLengthNL));
154	  // uploadLength: 64 bits
155	  uint64_t uploadLengthNL = 0;
156	#ifdef ENABLE_BITTORRENT
157	  if (torrentDownload) {
158	    uploadLengthNL = hton64(btRuntime_->getUploadLengthAtStartup() +
159	                            dctx_->getNetStat().getSessionUploadLength());
160	  }
161	#endif // ENABLE_BITTORRENT
162	  WRITE_CHECK(fp, &uploadLengthNL, sizeof(uploadLengthNL));
163	  // bitfieldLength: 32 bits
164	  uint32_t bitfieldLengthNL = htonl(pieceStorage_->getBitfieldLength());
165	  WRITE_CHECK(fp, &bitfieldLengthNL, sizeof(bitfieldLengthNL));
166	  // bitfield
167	  WRITE_CHECK(fp, pieceStorage_->getBitfield(),
168	              pieceStorage_->getBitfieldLength());
169	  // the number of in-flight piece: 32 bits
170	  // TODO implement this
171	  uint32_t numInFlightPieceNL = htonl(pieceStorage_->countInFlightPiece());
172	  WRITE_CHECK(fp, &numInFlightPieceNL, sizeof(numInFlightPieceNL));
173	  std::vector<std::shared_ptr<Piece>> inFlightPieces;
174	  inFlightPieces.reserve(pieceStorage_->countInFlightPiece());
175	  pieceStorage_->getInFlightPieces(inFlightPieces);
176	  for (std::vector<std::shared_ptr<Piece>>::const_iterator
177	           itr = inFlightPieces.begin(),
178	           eoi = inFlightPieces.end();
179	       itr != eoi; ++itr) {
180	    uint32_t indexNL = htonl((*itr)->getIndex());
181	    WRITE_CHECK(fp, &indexNL, sizeof(indexNL));
182	    uint32_t lengthNL = htonl((*itr)->getLength());
183	    WRITE_CHECK(fp, &lengthNL, sizeof(lengthNL));
184	    uint32_t bitfieldLengthNL = htonl((*itr)->getBitfieldLength());
185	    WRITE_CHECK(fp, &bitfieldLengthNL, sizeof(bitfieldLengthNL));
186	    WRITE_CHECK(fp, (*itr)->getBitfield(), (*itr)->getBitfieldLength());
187	  }
188	  if (fp.close() == EOF) {
189	    throw DL_ABORT_EX(fmt(EX_SEGMENT_FILE_WRITE, filename_.c_str()));
190	  }
191	}
