193	void DefaultBtProgressInfoFile::save()
194	{
195	  SHA1IOFile sha1io;
196	
197	  save(sha1io);
198	
199	  auto digest = sha1io.digest();
200	  if (digest == lastDigest_) {
201	    // We don't write control file if the content is not changed.
202	    return;
203	  }
204	
205	  lastDigest_ = std::move(digest);
206	
207	  A2_LOG_INFO(fmt(MSG_SAVING_SEGMENT_FILE, filename_.c_str()));
208	  std::string filenameTemp = filename_;
209	  filenameTemp += "__temp";
210	  {
211	    BufferedFile fp(filenameTemp.c_str(), BufferedFile::WRITE);
212	    if (!fp) {
213	      throw DL_ABORT_EX(fmt(EX_SEGMENT_FILE_WRITE, filename_.c_str()));
214	    }
215	
216	    save(fp);
217	  }
218	
219	  A2_LOG_INFO(MSG_SAVED_SEGMENT_FILE);
220	
221	  if (!File(filenameTemp).renameTo(filename_)) {
222	    throw DL_ABORT_EX(fmt(EX_SEGMENT_FILE_WRITE, filename_.c_str()));
223	  }
224	}
225	
226	#define READ_CHECK(fp, ptr, count)                                             \
227	  if (fp.read((ptr), (count)) != (count)) {                                    \
228	    throw DL_ABORT_EX(fmt(EX_SEGMENT_FILE_READ, filename_.c_str()));           \
229	  }
