231	// It is assumed that integers are saved as:
232	// 1) host byte order if version == 0000
233	// 2) network byte order if version == 0001
234	void DefaultBtProgressInfoFile::load()
235	{
236	  A2_LOG_INFO(fmt(MSG_LOADING_SEGMENT_FILE, filename_.c_str()));
237	  BufferedFile fp(filename_.c_str(), BufferedFile::READ);
238	  if (!fp) {
239	    throw DL_ABORT_EX(fmt(EX_SEGMENT_FILE_READ, filename_.c_str()));
240	  }
241	  unsigned char versionBuf[2];
242	  READ_CHECK(fp, versionBuf, sizeof(versionBuf));
243	  std::string versionHex = util::toHex(versionBuf, sizeof(versionBuf));
244	  int version;
245	  if ("0000" == versionHex) {
246	    version = 0;
247	  }
248	  else if ("0001" == versionHex) {
249	    version = 1;
250	  }
251	  else {
252	    throw DL_ABORT_EX(
253	        fmt("Unsupported ctrl file version: %s", versionHex.c_str()));
254	  }
255	  unsigned char extension[4];
256	  READ_CHECK(fp, extension, sizeof(extension));
257	  bool infoHashCheckEnabled = false;
258	  if (extension[3] & 1 && isTorrentDownload()) {
259	    infoHashCheckEnabled = true;
260	    A2_LOG_DEBUG("InfoHash checking enabled.");
261	  }
262	
263	  uint32_t infoHashLength;
264	  READ_CHECK(fp, &infoHashLength, sizeof(infoHashLength));
265	  if (version >= 1) {
266	    infoHashLength = ntohl(infoHashLength);
267	  }
268	  if (infoHashLength > INFO_HASH_LENGTH ||
269	      (infoHashLength != INFO_HASH_LENGTH && infoHashCheckEnabled)) {
270	    throw DL_ABORT_EX(fmt("Invalid info hash length: %d", infoHashLength));
271	  }
272	  if (infoHashLength > 0) {
273	    std::array<unsigned char, INFO_HASH_LENGTH> savedInfoHash;
274	    READ_CHECK(fp, savedInfoHash.data(), infoHashLength);
275	#ifdef ENABLE_BITTORRENT
276	    if (infoHashCheckEnabled) {
277	      const unsigned char* infoHash = bittorrent::getInfoHash(dctx_);
278	      if (memcmp(savedInfoHash.data(), infoHash, INFO_HASH_LENGTH) != 0) {
279	        throw DL_ABORT_EX(
280	            fmt("info hash mismatch. expected: %s, actual: %s",
281	                util::toHex(infoHash, INFO_HASH_LENGTH).c_str(),
282	                util::toHex(savedInfoHash.data(), infoHashLength).c_str()));
283	      }
284	    }
285	#endif // ENABLE_BITTORRENT
286	  }
287	
288	  uint32_t pieceLength;
289	  READ_CHECK(fp, &pieceLength, sizeof(pieceLength));
290	  if (version >= 1) {
291	    pieceLength = ntohl(pieceLength);
292	  }
293	
294	  if (pieceLength == 0) {
295	    throw DL_ABORT_EX("piece length must not be 0");
296	  }
297	
298	  uint64_t totalLength;
299	  READ_CHECK(fp, &totalLength, sizeof(totalLength));
300	  if (version >= 1) {
301	    totalLength = ntoh64(totalLength);
302	  }
303	  if (totalLength != static_cast<uint64_t>(dctx_->getTotalLength())) {
304	    throw DL_ABORT_EX(
305	        fmt("total length mismatch. expected: %" PRId64 ", actual: %" PRId64 "",
306	            dctx_->getTotalLength(), static_cast<int64_t>(totalLength)));
307	  }
308	  uint64_t uploadLength;
309	  READ_CHECK(fp, &uploadLength, sizeof(uploadLength));
310	  if (version >= 1) {
311	    uploadLength = ntoh64(uploadLength);
312	  }
313	#ifdef ENABLE_BITTORRENT
314	  if (isTorrentDownload()) {
315	    btRuntime_->setUploadLengthAtStartup(uploadLength);
316	  }
317	#endif // ENABLE_BITTORRENT
318	  // TODO implement the conversion mechanism between different piece length.
319	  uint32_t bitfieldLength;
320	  READ_CHECK(fp, &bitfieldLength, sizeof(bitfieldLength));
321	  if (version >= 1) {
322	    bitfieldLength = ntohl(bitfieldLength);
323	  }
324	  uint32_t expectedBitfieldLength =
325	      ((totalLength + pieceLength - 1) / pieceLength + 7) / 8;
326	  if (expectedBitfieldLength != bitfieldLength) {
327	    throw DL_ABORT_EX(fmt("bitfield length mismatch. expected: %d, actual: %d",
328	                          expectedBitfieldLength, bitfieldLength));
329	  }
330	
331	  auto savedBitfield = make_unique<unsigned char[]>((size_t)bitfieldLength);
332	  READ_CHECK(fp, savedBitfield.get(), bitfieldLength);
333	  if (pieceLength == static_cast<uint32_t>(dctx_->getPieceLength())) {
334	    pieceStorage_->setBitfield(savedBitfield.get(), bitfieldLength);
335	
336	    uint32_t numInFlightPiece;
337	    READ_CHECK(fp, &numInFlightPiece, sizeof(numInFlightPiece));
338	    if (version >= 1) {
339	      numInFlightPiece = ntohl(numInFlightPiece);
340	    }
341	    std::vector<std::shared_ptr<Piece>> inFlightPieces;
342	    inFlightPieces.reserve(numInFlightPiece);
343	    while (numInFlightPiece--) {
344	      uint32_t index;
345	      READ_CHECK(fp, &index, sizeof(index));
346	      if (version >= 1) {
347	        index = ntohl(index);
348	      }
349	      if (!(index < dctx_->getNumPieces())) {
350	        throw DL_ABORT_EX(fmt("piece index out of range: %u", index));
351	      }
352	      uint32_t length;
353	      READ_CHECK(fp, &length, sizeof(length));
354	      if (version >= 1) {
355	        length = ntohl(length);
356	      }
357	      if (!(length <= static_cast<uint32_t>(dctx_->getPieceLength()))) {
358	        throw DL_ABORT_EX(fmt("piece length out of range: %u", length));
359	      }
360	      auto piece = std::make_shared<Piece>(index, length);
361	      uint32_t bitfieldLength;
362	      READ_CHECK(fp, &bitfieldLength, sizeof(bitfieldLength));
363	      if (version >= 1) {
364	        bitfieldLength = ntohl(bitfieldLength);
365	      }
366	      if (piece->getBitfieldLength() != bitfieldLength) {
367	        throw DL_ABORT_EX(
368	            fmt("piece bitfield length mismatch."
369	                " expected: %lu actual: %u",
370	                static_cast<unsigned long>(piece->getBitfieldLength()),
371	                bitfieldLength));
372	      }
373	      auto pieceBitfield = make_unique<unsigned char[]>((size_t)bitfieldLength);
374	      READ_CHECK(fp, pieceBitfield.get(), bitfieldLength);
375	      piece->setBitfield(pieceBitfield.get(), bitfieldLength);
376	      piece->setHashType(dctx_->getPieceHashType());
377	
378	      inFlightPieces.push_back(piece);
379	    }
380	    pieceStorage_->addInFlightPiece(inFlightPieces);
381	  }
382	  else {
383	    uint32_t numInFlightPiece;
384	    READ_CHECK(fp, &numInFlightPiece, sizeof(numInFlightPiece));
385	    if (version >= 1) {
386	      numInFlightPiece = ntohl(numInFlightPiece);
387	    }
388	    BitfieldMan src(pieceLength, totalLength);
389	    src.setBitfield(savedBitfield.get(), bitfieldLength);
390	    if ((src.getCompletedLength() || numInFlightPiece) &&
391	        !option_->getAsBool(PREF_ALLOW_PIECE_LENGTH_CHANGE)) {
392	      throw DOWNLOAD_FAILURE_EXCEPTION2(
393	          "WARNING: Detected a change in piece length. You can proceed with"
394	          " --allow-piece-length-change=true, but you may lose some download"
395	          " progress.",
396	          error_code::PIECE_LENGTH_CHANGED);
397	    }
398	    BitfieldMan dest(dctx_->getPieceLength(), totalLength);
399	    util::convertBitfield(&dest, &src);
400	    pieceStorage_->setBitfield(dest.getBitfield(), dest.getBitfieldLength());
401	  }
402	  A2_LOG_INFO(MSG_LOADED_SEGMENT_FILE);
403	}
404	
405	void DefaultBtProgressInfoFile::removeFile()
406	{
407	  if (exists()) {
408	    File f(filename_);
409	    f.remove();
410	  }
411	}
412	
413	bool DefaultBtProgressInfoFile::exists()
414	{
415	  File f(filename_);
416	  if (f.isFile()) {
417	    A2_LOG_INFO(fmt(MSG_SEGMENT_FILE_EXISTS, filename_.c_str()));
418	    return true;
419	  }
420	  else {
421	    A2_LOG_INFO(fmt(MSG_SEGMENT_FILE_DOES_NOT_EXIST, filename_.c_str()));
422	    return false;
423	  }
424	}
425	
426	#ifdef ENABLE_BITTORRENT
427	void DefaultBtProgressInfoFile::setPeerStorage(
428	    const std::shared_ptr<PeerStorage>& peerStorage)
429	{
430	  peerStorage_ = peerStorage;
431	}
432	
433	void DefaultBtProgressInfoFile::setBtRuntime(
434	    const std::shared_ptr<BtRuntime>& btRuntime)
435	{
436	  btRuntime_ = btRuntime;
437	}
438	#endif // ENABLE_BITTORRENT
439	
440	} // namespace aria2
