210	void RequestGroup::closeFile()
211	{
212	  if (pieceStorage_) {
213	    pieceStorage_->flushWrDiskCacheEntry(true);
214	    pieceStorage_->getDiskAdaptor()->flushOSBuffers();
215	    pieceStorage_->getDiskAdaptor()->closeFile();
