64	bool CheckIntegrityCommand::executeInternal()
65	{
66	  if (getRequestGroup()->isHaltRequested()) {
67	    return true;
68	  }
69	  entry_->validateChunk();
70	  if (entry_->finished()) {
71	    // Enable control file saving here. See also
72	    // RequestGroup::processCheckIntegrityEntry() to know why this is
73	    // needed.
74	    getRequestGroup()->enableSaveControlFile();
75	    if (getRequestGroup()->downloadFinished()) {
76	      A2_LOG_NOTICE(
77	          fmt(MSG_VERIFICATION_SUCCESSFUL,
78	              getRequestGroup()->getDownloadContext()->getBasePath().c_str()));
79	      std::vector<std::unique_ptr<Command>> commands;
80	      entry_->onDownloadFinished(commands, getDownloadEngine());
81	      getDownloadEngine()->addCommand(std::move(commands));
82	    }
83	    else {
84	      A2_LOG_ERROR(
